import sys, os, subprocess, importlib.util

REQUIREMENTS = {            # import name -> pip package (replaces requirements.txt)
    "streamlit": "streamlit>=1.36",
    "pandas": "pandas",
    "PIL": "pillow",
    "reportlab": "reportlab",
}

def ensure_packages():
    missing = [pip for mod, pip in REQUIREMENTS.items() if importlib.util.find_spec(mod) is None]
    if missing:
        print("Installing missing packages:", ", ".join(missing))
        subprocess.check_call([sys.executable, "-m", "pip", "install", *missing])

ensure_packages()

