# If started with plain `python balarus_erp.py`, launch Streamlit automatically.
def _running_in_streamlit():
    try:
        from streamlit.runtime.scriptrunner import get_script_run_ctx
        return get_script_run_ctx(suppress_warning=True) is not None
    except TypeError:
        from streamlit.runtime.scriptrunner import get_script_run_ctx
        return get_script_run_ctx() is not None
    except Exception:
        return False

if not _running_in_streamlit():
    sys.exit(subprocess.call([sys.executable, "-m", "streamlit", "run", os.path.abspath(__file__),
                              "--theme.base=dark", "--theme.backgroundColor=#2B2D31",
                              "--theme.secondaryBackgroundColor=#000000", "--theme.textColor=#FFFFFF",
                              "--theme.primaryColor=#C8102E"]))


