DB_PATH = os.environ.get("DB_PATH", "balarus.db")
APP_PASSWORD = os.environ.get("APP_PASSWORD", "admin123")

SCHEMA = """
CREATE TABLE IF NOT EXISTS products(
 id INTEGER PRIMARY KEY, name TEXT NOT NULL, part_no TEXT, tractor_model TEXT, category TEXT,
 buy_price REAL DEFAULT 0, retail_price REAL DEFAULT 0, wholesale_price REAL DEFAULT 0,
 stock REAL DEFAULT 0, min_stock REAL DEFAULT 0);
CREATE TABLE IF NOT EXISTS parties(
 id INTEGER PRIMARY KEY, name TEXT NOT NULL, phone TEXT,
 type TEXT NOT NULL CHECK(type IN ('customer','supplier')));
CREATE TABLE IF NOT EXISTS accounts(id INTEGER PRIMARY KEY, name TEXT UNIQUE, opening REAL DEFAULT 0);
CREATE TABLE IF NOT EXISTS txns(
 id INTEGER PRIMARY KEY, date TEXT, account_id INTEGER, kind TEXT, amount REAL,
 party_id INTEGER, ref TEXT, note TEXT);
CREATE TABLE IF NOT EXISTS sales(
 id INTEGER PRIMARY KEY, date TEXT, party_id INTEGER, kind TEXT, total REAL, paid REAL, account_id INTEGER);
CREATE TABLE IF NOT EXISTS sale_items(
 id INTEGER PRIMARY KEY, sale_id INTEGER, product_id INTEGER, qty REAL, price REAL, cost REAL);
CREATE TABLE IF NOT EXISTS purchases(
 id INTEGER PRIMARY KEY, date TEXT, party_id INTEGER, total REAL, paid REAL, account_id INTEGER);
CREATE TABLE IF NOT EXISTS purchase_items(
 id INTEGER PRIMARY KEY, purchase_id INTEGER, product_id INTEGER, qty REAL, cost REAL);
"""

def conn():
    c = sqlite3.connect(DB_PATH, check_same_thread=False)
    c.row_factory = sqlite3.Row
    return c

def init_db():
    with conn() as c:
        c.executescript(SCHEMA)
        if c.execute("SELECT COUNT(*) FROM accounts").fetchone()[0] == 0:
            c.executemany("INSERT INTO accounts(name) VALUES(?)", [("Cash",),("Bank",),("bKash",)])
init_db()

def fetch(sql, params=()):
    with conn() as c: return c.execute(sql, params).fetchall()
def fetchone(sql, params=()):
    with conn() as c: return c.execute(sql, params).fetchone()
def execute(sql, params=()):
    with conn() as c:
        cur=c.execute(sql, params); c.commit(); return cur.lastrowid
def today(): return dt.date.today().isoformat()
def money(x): return f"৳{float(x or 0):,.2f}"

def accounts(): return fetch("SELECT * FROM accounts ORDER BY id")
def account_balances():
    return fetch("SELECT a.id,a.name,a.opening+COALESCE(SUM(t.amount),0) balance FROM accounts a LEFT JOIN txns t ON t.account_id=a.id GROUP BY a.id ORDER BY a.id")
def party_due(p):
    if p["type"]=="customer":
        sales=fetchone("SELECT COALESCE(SUM(total-paid),0) x FROM sales WHERE party_id=?",(p["id"],))["x"]
        received=fetchone("SELECT COALESCE(SUM(amount),0) x FROM txns WHERE party_id=? AND kind='due_in'",(p["id"],))["x"]
        return sales-received
    purchases=fetchone("SELECT COALESCE(SUM(total-paid),0) x FROM purchases WHERE party_id=?",(p["id"],))["x"]
    payments=fetchone("SELECT COALESCE(SUM(amount),0) x FROM txns WHERE party_id=? AND kind='due_out'",(p["id"],))["x"]
    return purchases+payments
def parties(kind=None):
    if kind: return fetch("SELECT * FROM parties WHERE type=? ORDER BY name",(kind,))
    return fetch("SELECT * FROM parties ORDER BY name")
def product_list(): return fetch("SELECT * FROM products ORDER BY name")
def fmt_table(rows): return [dict(r) for r in rows]

import html as _html
def _cell(v):
    if v is None: return "", ""
    if isinstance(v, bool): return str(v), ""
    if isinstance(v, int): return str(v), " class='num'"
    if isinstance(v, float): return f"{v:,.2f}", " class='num'"
    return _html.escape(str(v)), ""

def show_table(data):
    """Black table with white text (replaces st.dataframe)."""
    rows = [dict(r) for r in data]
    if not rows:
        st.html("<div class='gray-empty'>No records yet.</div>"); return
    cols = list(rows[0].keys())
    head = "".join(f"<th>{_html.escape(str(c))}</th>" for c in cols)
    body = ""
    for r in rows:
        tds = ""
        for c in cols:
            txt, cls = _cell(r.get(c)); tds += f"<td{cls}>{txt}</td>"
        body += f"<tr>{tds}</tr>"
    st.html(f"<div class='tbl-wrap'><table class='gray-table'><thead><tr>{head}</tr></thead><tbody>{body}</tbody></table></div>")

def show_kv(d):
    show_table([{"Item": k, "Value": v} for k, v in d.items()])

# ---------------------------------------------------------------- Accounting engine
# Journal -> Ledger -> Financial statements are all built from the same records
# (sales, purchases, expenses, transfers, due payments) using double entry.
from xml.sax.saxutils import escape as _xml

AR, INV, AP = "Accounts Receivable", "Inventory", "Accounts Payable"
CAP, SALES, COGS, CLR = "Owner's Capital (Opening Balances)", "Sales Revenue", "Cost of Goods Sold", "Transfer Clearing"
OPENING_DATE = "0000-00-00"
TYPE_ORDER = {"asset": 0, "liability": 1, "equity": 2, "revenue": 3, "expense": 4}

def cash_names(): return [a["name"] for a in accounts()]

def acct_type(name, cash):
    if name in cash or name in (AR, INV, CLR): return "asset"
    if name == AP: return "liability"
    if name == CAP: return "equity"
    if name == SALES: return "revenue"
    return "expense"                       # Cost of Goods Sold and "Expense - ..." accounts

def build_journal():
    """Return a list of balanced journal entries, oldest first."""
    r2 = lambda x: round(float(x or 0), 2)
    accs = {a["id"]: a["name"] for a in accounts()}
    pname = {p["id"]: p["name"] for p in parties()}
    entries = []
    def add(date, ref, desc, kind, lines):
        lines = [(a, r2(d), r2(c)) for a, d, c in lines if r2(d) or r2(c)]
        if lines: entries.append({"date": date, "ref": ref, "desc": desc, "kind": kind, "lines": lines})

    for a in accounts():
        o = r2(a["opening"])
        lines = [(a["name"], o, 0), (CAP, 0, o)] if o >= 0 else [(a["name"], 0, -o), (CAP, -o, 0)]
        add(OPENING_DATE, "Opening", f"Opening balance - {a['name']}", "opening", lines)

    cogs = {r["sale_id"]: r2(r["c"]) for r in fetch("SELECT sale_id, SUM(qty*cost) c FROM sale_items GROUP BY sale_id")}
    for s in fetch("SELECT * FROM sales ORDER BY date, id"):
        total, paid = r2(s["total"]), r2(s["paid"]); c = cogs.get(s["id"], 0)
        who = pname.get(s["party_id"], "Walk-in customer")
        add(s["date"], f"Sale #{s['id']}", f"{(s['kind'] or 'retail').title()} sale - {who}", "sale",
            [(accs.get(s["account_id"], "Cash"), paid, 0), (AR, round(total - paid, 2), 0),
             (SALES, 0, total), (COGS, c, 0), (INV, 0, c)])

    for b in fetch("SELECT * FROM purchases ORDER BY date, id"):
        total, paid = r2(b["total"]), r2(b["paid"])
        add(b["date"], f"Purchase #{b['id']}", f"Purchase - {pname.get(b['party_id'], 'Supplier')}", "purchase",
            [(INV, total, 0), (accs.get(b["account_id"], "Cash"), 0, paid), (AP, 0, round(total - paid, 2))])

    for t in fetch("SELECT * FROM txns WHERE kind IN ('expense','transfer','due_in','due_out') ORDER BY date, id"):
        cash, amt, who = accs.get(t["account_id"], "Cash"), r2(t["amount"]), pname.get(t["party_id"], "")
        if t["kind"] == "expense":
            cat = (t["ref"] or "").strip().title() or "General"
            add(t["date"], f"Expense #{t['id']}", t["note"] or cat, "expense", [(f"Expense - {cat}", -amt, 0), (cash, 0, -amt)])
        elif t["kind"] == "transfer":
            lines = [(cash, amt, 0), (CLR, 0, amt)] if amt >= 0 else [(cash, 0, -amt), (CLR, -amt, 0)]
            add(t["date"], f"Transfer #{t['id']}", t["ref"] or "Transfer", "transfer", lines)
        elif t["kind"] == "due_in":
            add(t["date"], f"Receipt #{t['id']}", f"Received from {who}", "due_in", [(cash, amt, 0), (AR, 0, amt)])
        else:
            add(t["date"], f"Payment #{t['id']}", f"Paid to {who}", "due_out", [(AP, -amt, 0), (cash, 0, -amt)])
    entries.sort(key=lambda e: e["date"])  # stable: keeps entry order within a day
    return entries

def journal_lines():
    out = []
    for i, e in enumerate(build_journal()):
        for a, d, c in e["lines"]:
            out.append({"date": e["date"], "ref": e["ref"], "desc": e["desc"], "kind": e["kind"],
                        "account": a, "debit": d, "credit": c, "entry": i})
    return out

# ---- periods: daily / weekly / monthly / yearly / custom
def period_range(kind, d, start=None, end=None):
    if kind == "Daily": return d, d
    if kind == "Weekly":
        s = d - dt.timedelta(days=d.weekday()); return s, s + dt.timedelta(days=6)
    if kind == "Monthly":
        s = d.replace(day=1); return s, (s.replace(day=28) + dt.timedelta(days=4)).replace(day=1) - dt.timedelta(days=1)
    if kind == "Yearly": return dt.date(d.year, 1, 1), dt.date(d.year, 12, 31)
    return start, end

def period_label(kind, s, e):
    f = lambda x: x.strftime("%d %b %Y")
    return f"{kind}: {f(s)}" if s == e else f"{kind}: {f(s)} to {f(e)}"

def period_picker(key):
    c1, c2, c3 = st.columns(3)
    kind = c1.selectbox("Period", ["Daily", "Weekly", "Monthly", "Yearly", "Custom"], index=2, key=key + "_k")
    if kind == "Custom":
        s = c2.date_input("From", dt.date.today().replace(day=1), key=key + "_s")
        e = c3.date_input("To", dt.date.today(), key=key + "_e")
        if e < s: s, e = e, s
    else:
        d = c2.date_input("Pick any date in the period", dt.date.today(), key=key + "_d")
        s, e = period_range(kind, d)
    st.caption(f"Showing {period_label(kind, s, e)}  (weeks run Monday to Sunday)")
    return kind, s, e

# ---- ledgers
def ledger_rows(events, sign, s, e):
    """events: (date, ref, description, debit, credit). sign=+1 debit-normal, -1 credit-normal."""
    opening = round(sum((d - c) * sign for dte, _, _, d, c in events if dte < s), 2)
    bal, rows = opening, []
    for dte, ref, desc, d, c in events:
        if s <= dte <= e:
            bal = round(bal + (d - c) * sign, 2)
            rows.append({"Date": "Opening" if dte == OPENING_DATE else dte, "Ref": ref, "Description": desc,
                         "Debit": d or None, "Credit": c or None, "Balance": bal})
    edge = lambda text, b: {"Date": "", "Ref": "", "Description": text, "Debit": None, "Credit": None, "Balance": b}
    return [edge("Opening balance", opening)] + rows + [edge("Closing balance", bal)], opening, bal

def account_events(L, account):
    return [(x["date"], x["ref"], x["desc"], x["debit"], x["credit"]) for x in L if x["account"] == account]

def party_events(p):
    ev = []
    if p["type"] == "customer":
        for s in fetch("SELECT id,date,total,paid FROM sales WHERE party_id=? ORDER BY date,id", (p["id"],)):
            ev.append((s["date"], f"Sale #{s['id']}", "Invoice", s["total"], 0.0))
            if s["paid"]: ev.append((s["date"], f"Sale #{s['id']}", "Paid at sale", 0.0, s["paid"]))
        for t in fetch("SELECT id,date,amount FROM txns WHERE party_id=? AND kind='due_in' ORDER BY date,id", (p["id"],)):
            ev.append((t["date"], f"Receipt #{t['id']}", "Payment received", 0.0, t["amount"]))
        sign = 1
    else:
        for b in fetch("SELECT id,date,total,paid FROM purchases WHERE party_id=? ORDER BY date,id", (p["id"],)):
            ev.append((b["date"], f"Purchase #{b['id']}", "Bill", 0.0, b["total"]))
            if b["paid"]: ev.append((b["date"], f"Purchase #{b['id']}", "Paid at purchase", b["paid"], 0.0))
        for t in fetch("SELECT id,date,amount FROM txns WHERE party_id=? AND kind='due_out' ORDER BY date,id", (p["id"],)):
            ev.append((t["date"], f"Payment #{t['id']}", "Payment made", -t["amount"], 0.0))
        sign = -1
    ev.sort(key=lambda x: x[0])
    return ev, sign

# ---- financial statements: rows are (label, amount or None, style)  style: "h" heading, "t" total, "" normal
def _bal(lines, test, sign=1):
    return round(sum((x["debit"] - x["credit"]) * sign for x in lines if test(x["account"])), 2)

def income_statement(L, s, e):
    cur = [x for x in L if s <= x["date"] <= e]
    sales, cogs = _bal(cur, lambda a: a == SALES, -1), _bal(cur, lambda a: a == COGS)
    rows = [("Revenue", None, "h"), ("Sales revenue", sales, ""), ("Total revenue", sales, "t"),
            ("Cost of goods sold", None, "h"), ("Cost of goods sold", cogs, ""),
            ("Gross profit", round(sales - cogs, 2), "t"), ("Operating expenses", None, "h")]
    exp = sorted({x["account"] for x in cur if x["account"].startswith("Expense - ")}); tot = 0.0
    for a in exp:
        v = _bal(cur, lambda n, a=a: n == a); tot += v; rows.append((a[10:], v, ""))
    if not exp: rows.append(("No expenses recorded", 0.0, ""))
    tot = round(tot, 2); net = round(sales - cogs - tot, 2)
    return rows + [("Total operating expenses", tot, "t"), ("Net profit / (loss)", net, "t")], net

def balance_sheet(L, e, cash):
    up = [x for x in L if x["date"] <= e]
    rows, ta = [("Assets", None, "h")], 0.0
    for a in cash + [AR, INV]:
        v = _bal(up, lambda n, a=a: n == a); rows.append((a, v, "")); ta += v
    clr = _bal(up, lambda n: n == CLR)
    if clr: rows.append((CLR, clr, "")); ta += clr
    ta = round(ta, 2); ap = _bal(up, lambda n: n == AP, -1); cap = _bal(up, lambda n: n == CAP, -1)
    ret = round(_bal(up, lambda n: n == SALES, -1) - _bal(up, lambda n: n == COGS)
                - _bal(up, lambda n: n.startswith("Expense - ")), 2)
    tle = round(ap + cap + ret, 2)
    rows += [("Total assets", ta, "t"), ("Liabilities", None, "h"), (AP, ap, ""), ("Total liabilities", ap, "t"),
             ("Equity", None, "h"), ("Owner's capital (opening balances)", cap, ""),
             ("Retained earnings (profit to date)", ret, ""), ("Total equity", round(cap + ret, 2), "t"),
             ("Total liabilities + equity", tle, "t")]
    return rows, ta, tle

def cash_flow(L, s, e, cash):
    cl = [x for x in L if x["account"] in cash]
    opening = round(sum(x["debit"] - x["credit"] for x in cl if x["date"] < s), 2)
    cur = [x for x in cl if s <= x["date"] <= e]
    k = lambda kind: round(sum(x["debit"] - x["credit"] for x in cur if x["kind"] == kind), 2)
    net = round(sum(x["debit"] - x["credit"] for x in cur), 2)
    rows = [("Opening cash and bank balance", opening, "t"), ("Cash received", None, "h"),
            ("Sales received", k("sale"), ""), ("Customer dues collected", k("due_in"), ""),
            ("Cash paid", None, "h"), ("Purchases paid", k("purchase"), ""),
            ("Supplier dues paid", k("due_out"), ""), ("Expenses paid", k("expense"), ""),
            ("Net change in cash", net, "t"), ("Closing cash and bank balance", round(opening + net, 2), "t")]
    return rows, round(opening + net, 2)

def trial_balance(L, e, cash):
    up = [x for x in L if x["date"] <= e]; rows, td, tc = [], 0.0, 0.0
    for a in sorted({x["account"] for x in up}, key=lambda a: (TYPE_ORDER[acct_type(a, cash)], a)):
        n = round(sum(x["debit"] - x["credit"] for x in up if x["account"] == a), 2)
        dr, cr = (n, 0.0) if n > 0 else (0.0, -n); td += dr; tc += cr
        rows.append({"Account": a, "Type": acct_type(a, cash).title(), "Debit": dr or None, "Credit": cr or None})
    td, tc = round(td, 2), round(tc, 2)
    return rows + [{"Account": "Total", "Type": "", "Debit": td, "Credit": tc}], td, tc

def show_statement(rows):
    body = ""
    for label, val, kind in rows:
        cls = {"h": "sec", "t": "tot"}.get(kind, "")
        if val is None: body += f"<tr class='{cls}'><td colspan='2'>{_html.escape(label)}</td></tr>"
        else: body += f"<tr class='{cls}'><td>{_html.escape(label)}</td><td class='num'>{val:,.2f}</td></tr>"
    st.html(f"<div class='tbl-wrap'><table class='gray-table'><tbody>{body}</tbody></table></div>")

# ---- PDF printing
def _f(v):
    if v is None or v == "": return ""
    return f"{v:,.2f}" if isinstance(v, float) else str(v)

def pdf_rows(rows, cols):
    return [[_f(r.get(c)) for c in cols] for r in rows]

def stmt_block(heading, rows):
    return {"heading": heading, "header": ["Item", "Amount (Tk)"], "num_cols": [1], "widths": [0.68, 0.32],
            "rows": [[l, _f(v)] for l, v, _ in rows], "bold": {i for i, (_, _, k) in enumerate(rows) if k in ("h", "t")}}

def build_pdf(title, period_text, blocks, wide=False):
    """blocks: dicts with heading, header, rows (lists of strings), num_cols, widths (fractions), bold (row indexes)."""
    from reportlab.lib import colors
    from reportlab.lib.enums import TA_LEFT, TA_RIGHT
    from reportlab.lib.pagesizes import A4, landscape
    from reportlab.lib.styles import ParagraphStyle
    from reportlab.lib.units import mm
    from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, KeepTogether
    from reportlab.platypus import Image as RLImage
    page = landscape(A4) if wide else A4
    buf = io.BytesIO(); width = page[0] - 28 * mm
    doc = SimpleDocTemplate(buf, pagesize=page, leftMargin=14*mm, rightMargin=14*mm, topMargin=12*mm,
                            bottomMargin=16*mm, title=f"{SHOP} - {title}", author=SHOP)
    navy, red = colors.HexColor(NAVY), colors.HexColor(RED)
    ps = lambda name, **kw: ParagraphStyle(name, fontName=kw.pop("font", "Helvetica"), **kw)
    s_shop = ps("shop", font="Helvetica-Bold", fontSize=17, textColor=navy, leading=20)
    s_tag = ps("tag", fontSize=8.5, textColor=red, leading=11)
    s_title = ps("title", font="Helvetica-Bold", fontSize=14, textColor=navy, spaceBefore=8, spaceAfter=2, leading=17)
    s_sub = ps("sub", fontSize=9, textColor=colors.HexColor("#444444"), spaceAfter=6, leading=12)
    s_h = ps("h", font="Helvetica-Bold", fontSize=11, textColor=navy, spaceBefore=10, spaceAfter=4, leading=13)

    story = []
    logo = ""
    if LOGO:
        w = 22 * mm; logo = RLImage(io.BytesIO(base64.b64decode(LOGO_B64)), width=w, height=w * LOGO.height / LOGO.width)
    head = Table([[logo, [Paragraph(_xml(SHOP), s_shop), Paragraph(_xml(TAGLINE), s_tag)]]],
                 colWidths=[26 * mm, width - 26 * mm])
    head.setStyle(TableStyle([("VALIGN", (0, 0), (-1, -1), "MIDDLE"), ("LINEBELOW", (0, 0), (-1, 0), 1.4, navy),
                              ("BOTTOMPADDING", (0, 0), (-1, -1), 6), ("LEFTPADDING", (0, 0), (-1, -1), 0)]))
    story += [head, Paragraph(_xml(title), s_title), Paragraph(_xml(period_text), s_sub)]

    for b in blocks:
        num, bold, nc = set(b.get("num_cols", [])), set(b.get("bold", [])), len(b["header"])
        cell = lambda c, color=colors.black: ParagraphStyle(f"c{c}{color}", fontName="Helvetica", fontSize=8.5, leading=10.5,
                                                            textColor=color, alignment=TA_RIGHT if c in num else TA_LEFT)
        data = [[Paragraph(f"<b>{_xml(h)}</b>", cell(c, colors.white)) for c, h in enumerate(b["header"])]]
        for i, r in enumerate(b["rows"]):
            data.append([Paragraph((f"<b>{_xml(str(v))}</b>" if i in bold else _xml(str(v))).replace("  ", "&nbsp;&nbsp;"), cell(c))
                         for c, v in enumerate(r)])
        fr = b.get("widths") or [1 / nc] * nc
        t = Table(data, colWidths=[width * x for x in fr], repeatRows=1)
        st_ = [("BACKGROUND", (0, 0), (-1, 0), navy), ("VALIGN", (0, 0), (-1, -1), "TOP"),
               ("ROWBACKGROUNDS", (0, 1), (-1, -1), [colors.white, colors.HexColor("#F2F5FB")]),
               ("LINEBELOW", (0, 1), (-1, -1), 0.25, colors.HexColor("#C9D1E3")),
               ("TOPPADDING", (0, 0), (-1, -1), 3), ("BOTTOMPADDING", (0, 0), (-1, -1), 3)]
        for i in bold:
            st_ += [("BACKGROUND", (0, i + 1), (-1, i + 1), colors.HexColor("#E6ECF8")),
                    ("LINEABOVE", (0, i + 1), (-1, i + 1), 0.8, navy)]
        t.setStyle(TableStyle(st_))
        if not b["rows"]: parts = [Paragraph(_xml(b["heading"]), s_h), Paragraph("No records in this period.", s_sub)]
        else: parts = [Paragraph(_xml(b["heading"]), s_h), t]
        story += [KeepTogether(parts)] if len(b["rows"]) <= 35 else parts

    def footer(canvas, d):
        canvas.saveState(); canvas.setFont("Helvetica", 7.5); canvas.setFillColor(colors.HexColor("#555555"))
        canvas.drawString(14 * mm, 9 * mm, f"{SHOP} - {title} - generated {dt.datetime.now():%d %b %Y %H:%M}")
        canvas.drawRightString(page[0] - 14 * mm, 9 * mm, f"Page {d.page}"); canvas.restoreState()
    doc.build(story, onFirstPage=footer, onLaterPages=footer)
    return buf.getvalue()


